CREATE DATABASE IF NOT EXISTS berjaya_hills CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE berjaya_hills;
SET FOREIGN_KEY_CHECKS=0;
DROP VIEW IF EXISTS vw_calendar_events, vw_booking_summary, vw_upcoming_public_events;
DROP TABLE IF EXISTS contact_inquiries, audit_logs, system_settings, email_logs, notifications, user_notification_preferences, notification_templates, location_gallery, event_gallery, gallery_images, gallery_albums, training_sessions, staff_activities, day_tripper_activities, csr_activities, booking_change_requests, booking_change_history, booking_status_history, booking_food, food_menus, booking_facilities, booking_rooms, bookings, event_financial_estimates, event_timeline_items, event_venues, events, event_categories, room_types, venue_maintenance, venue_images, venue_facilities, facilities, venues, location_images, locations, location_categories, password_resets, user_roles, role_permissions, users, permissions, roles;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(50), company_name VARCHAR(190), job_title VARCHAR(120), account_status ENUM('pending','approved','rejected','suspended','inactive') NOT NULL DEFAULT 'pending', rejection_reason TEXT NULL, email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(account_status)) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id INT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE location_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, slug VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, location_type VARCHAR(80), description TEXT, address VARCHAR(255), latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, is_featured TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES location_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE location_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location_id BIGINT UNSIGNED NOT NULL, image_path VARCHAR(255) NOT NULL, alt_text VARCHAR(190), sort_order INT DEFAULT 0, is_primary TINYINT(1) DEFAULT 0, FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE venues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location_id BIGINT UNSIGNED NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, venue_type VARCHAR(100), description TEXT, capacity INT UNSIGNED DEFAULT 0, area_sqft DECIMAL(10,2) NULL, rate DECIMAL(12,2) DEFAULT 0, status ENUM('available','unavailable','maintenance') DEFAULT 'available', featured TINYINT(1) DEFAULT 0, bookable TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE facilities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(100), description TEXT, quantity INT DEFAULT 1, unit_rate DECIMAL(12,2) DEFAULT 0, status ENUM('available','maintenance','inactive') DEFAULT 'available', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE venue_facilities (venue_id BIGINT UNSIGNED NOT NULL, facility_id BIGINT UNSIGNED NOT NULL, quantity INT DEFAULT 1, PRIMARY KEY(venue_id,facility_id), FOREIGN KEY(venue_id) REFERENCES venues(id) ON DELETE CASCADE, FOREIGN KEY(facility_id) REFERENCES facilities(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE venue_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, venue_id BIGINT UNSIGNED NOT NULL, image_path VARCHAR(255) NOT NULL, alt_text VARCHAR(190), sort_order INT DEFAULT 0, is_primary TINYINT(1) DEFAULT 0, FOREIGN KEY(venue_id) REFERENCES venues(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE venue_maintenance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, venue_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, reason VARCHAR(255), status ENUM('scheduled','active','completed','cancelled') DEFAULT 'scheduled', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(venue_id) REFERENCES venues(id) ON DELETE CASCADE, INDEX(venue_id,starts_at,ends_at)) ENGINE=InnoDB;
CREATE TABLE room_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT, capacity INT DEFAULT 1, nightly_rate DECIMAL(12,2) DEFAULT 0, quantity INT DEFAULT 0, status ENUM('available','maintenance','inactive') DEFAULT 'available') ENGINE=InnoDB;

CREATE TABLE event_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255), color_hex CHAR(7) DEFAULT '#C8A96B') ENGINE=InnoDB;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_user_id BIGINT UNSIGNED NULL, category_id INT UNSIGNED NULL, title VARCHAR(190) NOT NULL, description TEXT, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, expected_pax INT DEFAULT 0, status ENUM('draft','pending','confirmed','completed','cancelled','rejected') DEFAULT 'draft', is_public TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(category_id) REFERENCES event_categories(id) ON DELETE SET NULL, INDEX(start_at,end_at,status)) ENGINE=InnoDB;
CREATE TABLE event_venues (event_id BIGINT UNSIGNED NOT NULL, venue_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(event_id,venue_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(venue_id) REFERENCES venues(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE event_timeline_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, item_time DATETIME NOT NULL, title VARCHAR(190) NOT NULL, description TEXT, sort_order INT DEFAULT 0, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE event_financial_estimates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, estimated_revenue DECIMAL(14,2) DEFAULT 0, estimated_spending DECIMAL(14,2) DEFAULT 0, notes TEXT, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_ref VARCHAR(30) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, event_id BIGINT UNSIGNED NOT NULL, status ENUM('draft','pending_review','pending_info','rejected','confirmed','cancelled','completed') DEFAULT 'draft', submitted_at DATETIME NULL, reviewed_at DATETIME NULL, reviewed_by BIGINT UNSIGNED NULL, rejection_reason TEXT NULL, notes TEXT, total_estimate DECIMAL(14,2) DEFAULT 0, payment_method VARCHAR(80) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(user_id,status)) ENGINE=InnoDB;
CREATE TABLE booking_rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, room_type_id BIGINT UNSIGNED NOT NULL, quantity INT DEFAULT 1, nights INT DEFAULT 1, rate DECIMAL(12,2) DEFAULT 0, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE booking_facilities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, facility_id BIGINT UNSIGNED NOT NULL, quantity INT DEFAULT 1, rate DECIMAL(12,2) DEFAULT 0, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(facility_id) REFERENCES facilities(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE food_menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, menu_type VARCHAR(100), description TEXT, price_per_pax DECIMAL(12,2) DEFAULT 0, status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE booking_food (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, food_menu_id BIGINT UNSIGNED NOT NULL, pax INT DEFAULT 1, rate DECIMAL(12,2) DEFAULT 0, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(food_menu_id) REFERENCES food_menus(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE booking_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, old_status VARCHAR(50), new_status VARCHAR(50) NOT NULL, changed_by BIGINT UNSIGNED NULL, note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE booking_change_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, field_name VARCHAR(100) NOT NULL, old_value TEXT, new_value TEXT, changed_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE booking_change_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, requested_by BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, proposed_start_at DATETIME NULL, proposed_end_at DATETIME NULL, proposed_venue_id BIGINT UNSIGNED NULL, status ENUM('pending','approved','rejected') DEFAULT 'pending', reviewed_by BIGINT UNSIGNED NULL, review_note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(proposed_venue_id) REFERENCES venues(id) ON DELETE SET NULL, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;

CREATE TABLE csr_activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, activity_date DATE, category VARCHAR(100), description TEXT, participants INT DEFAULT 0, budget DECIMAL(12,2) DEFAULT 0, status ENUM('planned','ongoing','completed','cancelled') DEFAULT 'planned', created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE day_tripper_activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, activity_date DATE, pax INT DEFAULT 0, package_name VARCHAR(150), revenue DECIMAL(12,2) DEFAULT 0, status ENUM('planned','confirmed','completed','cancelled') DEFAULT 'planned', created_by BIGINT UNSIGNED NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE staff_activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, activity_date DATE, department VARCHAR(120), participants INT DEFAULT 0, description TEXT, status ENUM('planned','completed','cancelled') DEFAULT 'planned', created_by BIGINT UNSIGNED NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE training_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, trainer VARCHAR(150), department VARCHAR(120), venue_id BIGINT UNSIGNED NULL, starts_at DATETIME, ends_at DATETIME, participants INT DEFAULT 0, status ENUM('planned','ongoing','completed','cancelled') DEFAULT 'planned', created_by BIGINT UNSIGNED NULL, FOREIGN KEY(venue_id) REFERENCES venues(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;

CREATE TABLE gallery_albums (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, slug VARCHAR(210) NOT NULL UNIQUE, description TEXT, cover_image VARCHAR(255), is_public TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE gallery_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, album_id BIGINT UNSIGNED NOT NULL, image_path VARCHAR(255) NOT NULL, caption VARCHAR(255), sort_order INT DEFAULT 0, FOREIGN KEY(album_id) REFERENCES gallery_albums(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE event_gallery (event_id BIGINT UNSIGNED NOT NULL, gallery_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(event_id,gallery_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(gallery_id) REFERENCES gallery_albums(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE location_gallery (location_id BIGINT UNSIGNED NOT NULL, gallery_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(location_id,gallery_id), FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE, FOREIGN KEY(gallery_id) REFERENCES gallery_albums(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE notification_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, channel ENUM('in_app','email','both') DEFAULT 'both', subject_template VARCHAR(255), body_template TEXT, is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE user_notification_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, booking_updates TINYINT(1) DEFAULT 1, event_reminders TINYINT(1) DEFAULT 1, announcements TINYINT(1) DEFAULT 1, email_enabled TINYINT(1) DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, type VARCHAR(80) NOT NULL, title VARCHAR(190) NOT NULL, message TEXT NOT NULL, link_url VARCHAR(255), is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(user_id,is_read)) ENGINE=InnoDB;
CREATE TABLE email_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, recipient_email VARCHAR(190) NOT NULL, subject VARCHAR(255) NOT NULL, body LONGTEXT, status ENUM('queued','sent','failed') DEFAULT 'queued', error_message TEXT NULL, sent_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;

CREATE TABLE contact_inquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, company VARCHAR(190) NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(50) NULL, event_type VARCHAR(100) NOT NULL, estimated_guests INT UNSIGNED NOT NULL DEFAULT 1, preferred_date DATE NULL, contact_preference ENUM('Email','Phone','WhatsApp') NOT NULL DEFAULT 'Email', message TEXT NOT NULL, status ENUM('new','in_progress','responded','closed') NOT NULL DEFAULT 'new', assigned_to BIGINT UNSIGNED NULL, admin_note TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status), INDEX(created_at), FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80), entity_id BIGINT UNSIGNED NULL, old_data JSON NULL, new_data JSON NULL, ip_address VARCHAR(45), user_agent VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(entity_type,entity_id), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE system_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(120) NOT NULL UNIQUE, setting_value TEXT, setting_group VARCHAR(80) DEFAULT 'general', is_public TINYINT(1) DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;

INSERT INTO roles(name,description) VALUES ('Administrator','Full system administration and governance'),('Management','Reviews and approves user bookings and change requests'),('Event','Event, calendar, venue and operational booking management'),('HR','Staff activities and training management'),('Author','Gallery, CSR and content management'),('IT','System, user, permission and technical management'),('Registered User','Approved user who can create and manage own bookings');
INSERT INTO permissions(name,description) VALUES ('dashboard.view','View dashboards'),('users.manage','Manage users'),('bookings.create','Create bookings'),('bookings.manage','Review bookings'),('bookings.change_request','Request booking changes'),('venues.manage','Manage venues'),('events.manage','Manage events'),('activities.manage','Manage activities'),('gallery.manage','Manage gallery'),('reports.view','View reports'),('settings.manage','Manage settings'),('audit.view','View audit trail'),('notifications.manage','Manage notifications');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='Administrator';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','bookings.manage','reports.view','notifications.manage') WHERE r.name='Management';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','events.manage','venues.manage','bookings.manage') WHERE r.name='Event';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','activities.manage') WHERE r.name='HR';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','activities.manage','gallery.manage') WHERE r.name='Author';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','users.manage','settings.manage','audit.view') WHERE r.name='IT';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('dashboard.view','bookings.create','bookings.change_request') WHERE r.name='Registered User';

