INSERT INTO venues(location_id,name,slug,venue_type,description,capacity,area_sqft,rate,featured,bookable)
SELECT l.id,l.name,l.slug,COALESCE(l.location_type,'Place'),l.description,0,0,0,l.is_featured,0
FROM locations l
WHERE l.slug IN ('colmar-tropicale-resort','the-chateau-spa-wellness-resort','berjaya-hills-golf-country-club','japanese-village','rabbit-park','berjaya-hills-adventure-park','colmar-tropicale-lookout-point-tower','colmar-tropicale-convention-center','masjid-berjaya-hills-resort','botanical-garden','berjaya-hills-horse-trails','coniferous-forest','9d-motion-adventure')
AND NOT EXISTS (SELECT 1 FROM venues v WHERE v.slug=l.slug);

INSERT INTO facilities(name,category,description,quantity,unit_rate) VALUES ('Projector','AV','HD projector',4,250),('PA System','AV','Professional sound system',3,650),('Round Table','Furniture','Banquet round table',40,35),('Banquet Chair','Furniture','Padded banquet chair',500,12),('Stage','Event','Portable stage platform',3,450),('Wireless Microphone','AV','Wireless handheld microphone',12,80);
INSERT INTO venue_facilities(venue_id,facility_id,quantity) SELECT v.id,f.id,CASE WHEN f.name='Banquet Chair' THEN 500 ELSE 2 END FROM venues v CROSS JOIN facilities f WHERE v.slug IN ('glass-hall','chateau-ballroom') AND f.name IN ('Projector','PA System','Round Table','Banquet Chair','Wireless Microphone');

-- Transfer all public Resort Explorer places into the unified Venues catalogue.
-- These records remain visible in Venues but are not bookable event spaces.
INSERT INTO venues(location_id,name,slug,venue_type,description,capacity,area_sqft,rate,featured,bookable)
SELECT l.id,l.name,l.slug,COALESCE(l.location_type,'Venue'),l.description,0,0,0,l.is_featured,0
FROM locations l
WHERE l.slug IN (
  'the-chateau','japanese-village','colmar-tropicale-resort','the-chateau-spa-wellness-resort',
  'berjaya-hills-golf-country-club','rabbit-park','berjaya-hills-adventure-park',
  'colmar-tropicale-lookout-point-tower','colmar-tropicale-convention-center',
  'masjid-berjaya-hills-resort','botanical-garden','berjaya-hills-horse-trails',
  'coniferous-forest','9d-motion-adventure'
)
AND NOT EXISTS (SELECT 1 FROM venues v WHERE v.slug=l.slug);

