CREATE OR REPLACE VIEW vw_calendar_events AS SELECT e.id,e.title,e.start_at,e.end_at,e.status,e.is_public,c.name category_name,c.color_hex,GROUP_CONCAT(v.name SEPARATOR ', ') venue_names FROM events e LEFT JOIN event_categories c ON c.id=e.category_id LEFT JOIN event_venues ev ON ev.event_id=e.id LEFT JOIN venues v ON v.id=ev.venue_id GROUP BY e.id;
CREATE OR REPLACE VIEW vw_booking_summary AS SELECT b.id,b.booking_ref,b.status,b.total_estimate,b.created_at,b.submitted_at,b.event_id,u.id user_id,u.full_name user_name,u.email,e.title event_title,e.start_at,e.end_at,e.expected_pax,GROUP_CONCAT(v.name SEPARATOR ', ') venue_names FROM bookings b JOIN users u ON u.id=b.user_id JOIN events e ON e.id=b.event_id LEFT JOIN event_venues ev ON ev.event_id=e.id LEFT JOIN venues v ON v.id=ev.venue_id GROUP BY b.id;
CREATE OR REPLACE VIEW vw_upcoming_public_events AS SELECT e.id,e.title,e.start_at,e.end_at,c.name category_name,c.color_hex,GROUP_CONCAT(v.name SEPARATOR ', ') venue_names FROM events e LEFT JOIN event_categories c ON c.id=e.category_id LEFT JOIN event_venues ev ON ev.event_id=e.id LEFT JOIN venues v ON v.id=ev.venue_id WHERE e.is_public=1 AND e.status='confirmed' AND e.start_at>=NOW() GROUP BY e.id;
